#include <iomanip>
#include <iostream>

int main() {
    const double fahrenheit = 100.0;
    const double limit_celsius = 80.0;
    // Deliberate baseline defect: compare unlike units.
    std::cout << "raw comparison="
              << (fahrenheit >= limit_celsius ? "ALERT" : "ok") << '\n';
    const double celsius = (fahrenheit - 32.0) * 5.0 / 9.0;
    std::cout << std::fixed << std::setprecision(1)
              << "normalized=" << celsius << " C\n";
    std::cout << "normalized comparison="
              << (celsius >= limit_celsius ? "ALERT" : "ok") << '\n';
}

#include <iostream>
#include <stdexcept>
#include <vector>

void direct_append(std::vector<int>& live, const std::vector<int>& batch) {
    for (int id : batch) {
        if (id <= 0) throw std::invalid_argument("bad id");
        live.push_back(id); // Defect: a later error leaves a partial batch.
    }
}
void staged_append(std::vector<int>& live, const std::vector<int>& batch) {
    auto candidate = live;
    for (int id : batch) {
        if (id <= 0) throw std::invalid_argument("bad id");
        candidate.push_back(id);
    }
    live.swap(candidate); // Commit only after all items pass.
}
int main() {
    std::vector<int> direct{10};
    std::vector<int> staged{10};
    const std::vector<int> batch{11, 0};
    try { direct_append(direct, batch); }
    catch (const std::invalid_argument&) {}
    try { staged_append(staged, batch); }
    catch (const std::invalid_argument&) {}
    std::cout << "direct count=" << direct.size() << '\n';
    std::cout << "staged count=" << staged.size() << '\n';
}

#include <iostream>
#include <vector>

struct Record {
    double celsius;
    bool alert_at_intake;
};
int main() {
    double limit = 80.0;
    std::vector<Record> history{{80.0, 80.0 >= limit}};
    limit = 100.0; // New policy is for future intake.
    int stored = 0;
    int recomputed = 0;
    for (const auto& row : history) {
        stored += row.alert_at_intake ? 1 : 0;
        recomputed += row.celsius >= limit ? 1 : 0;
    }
    std::cout << "stored alerts=" << stored << '\n';
    std::cout << "recomputed alerts=" << recomputed << '\n';
    std::cout << "future alert=" << (90.0 >= limit) << '\n';
}
